//! Golden-string tests for the Graphviz DOT dump (`src/dump.rs`).
//!
//! # How these goldens were obtained
//!
//! Issue #11 asks for them to be generated by running upstream's `dump` on the
//! same graph in C++ once and pasting the result. **That was not done, and
//! nothing here is evidence of a C++ run:** the development container has no
//! C++ compiler (no `g++`), so the goldens below were *derived by reading*
//! upstream's four `dump`/`_dump` functions -- `taskflow/core/taskflow.hpp`
//! lines 426-580 of Taskflow v4.1.0, commit `45366fe5` -- and applying the
//! identifier substitution documented in `src/dump.rs`: a node prints as
//! `p<arena index>` where upstream prints `p<node address>`, and the top-level
//! graph as `p0`/`cluster_p0` where upstream prints its address.
//!
//! The equivalent C++ is kept with each case so the goldens can be regenerated
//! anywhere a compiler exists. The *only* difference to expect from such a run
//! is in those identifiers; every other byte -- the `compound=true;`, the two
//! spaces per nesting level, the space before `]` in a node line, the trailing
//! newline -- is upstream's own and is asserted here exactly.
//!
//! For the same reason, the issue's "output parses with `dot`" check is **not
//! done**: there is no `graphviz` in the container either. It stays an open
//! item, and it was never part of the gate.
//!
//! One deliberate difference in how the graphs are *built*: upstream's
//! snippets use `emplace`/`precede`, which is another issue's API, so these
//! tests use the arena primitives and placeholder handles. That cannot change
//! the output -- a placeholder and a static task both fall through upstream's
//! shape `switch` to `default` and so print the same line -- and
//! `src/dump.rs`'s `a_static_handle_dumps_like_a_placeholder` asserts it.

use rustflow::{Handle, Task, Taskflow};

/// Upstream:
///
/// ```cpp
/// tf::Taskflow taskflow;
/// std::cout << taskflow.dump();
/// ```
///
/// The cluster is emitted even with nothing in it: upstream's module-stack
/// `_dump` pushes the top-level graph unconditionally and only the node loop
/// inside it is empty.
#[test]
fn an_empty_taskflow_dumps_an_empty_cluster() {
    let taskflow = Taskflow::new();
    assert_eq!(
        taskflow.dump(),
        concat!(
            "digraph Taskflow {\n",
            "  compound=true;\n",
            "  subgraph cluster_p0 {\n",
            "    label=\"Taskflow: p0\";\n",
            "  }\n",
            "}\n",
        )
    );
}

/// Upstream:
///
/// ```cpp
/// tf::Taskflow taskflow;
/// taskflow.placeholder();
/// std::cout << taskflow.dump();
/// ```
///
/// Both fallbacks for an absent name show up here: the taskflow's own label
/// and the node's label are each the id that upstream would print as an
/// address.
#[test]
fn one_unnamed_node_falls_back_to_its_id() {
    let mut taskflow = Taskflow::new();
    assert_eq!(
        taskflow.graph_mut().add_node(Handle::Placeholder),
        Task::new(0)
    );
    assert_eq!(
        taskflow.dump(),
        concat!(
            "digraph Taskflow {\n",
            "  compound=true;\n",
            "  subgraph cluster_p0 {\n",
            "    label=\"Taskflow: p0\";\n",
            "    p0[label=\"p0\" ];\n",
            "  }\n",
            "}\n",
        )
    );
}

/// Upstream:
///
/// ```cpp
/// tf::Taskflow taskflow("diamond");
/// auto [a, b, c, d] = taskflow.emplace(
///   [](){}, [](){}, [](){}, [](){}
/// );
/// a.name("a");
/// b.name("b");
/// c.name("c");
/// d.name("d");
/// a.precede(b, c);
/// b.precede(d);
/// c.precede(d);
/// std::cout << taskflow.dump();
/// ```
///
/// This is the case that pins the interleaving: upstream dumps a node and then
/// that node's own edges before moving to the next node, rather than all nodes
/// and then all edges.
#[test]
fn a_named_diamond_dumps_each_node_with_its_own_edges() {
    let mut taskflow = Taskflow::with_name("diamond");
    let graph = taskflow.graph_mut();
    let a = graph.add_named_node("a", Handle::Placeholder);
    let b = graph.add_named_node("b", Handle::Placeholder);
    let c = graph.add_named_node("c", Handle::Placeholder);
    let d = graph.add_named_node("d", Handle::Placeholder);
    graph.add_edge(a, b);
    graph.add_edge(a, c);
    graph.add_edge(b, d);
    graph.add_edge(c, d);

    assert_eq!(
        taskflow.dump(),
        concat!(
            "digraph Taskflow {\n",
            "  compound=true;\n",
            "  subgraph cluster_p0 {\n",
            "    label=\"Taskflow: diamond\";\n",
            "    p0[label=\"a\" ];\n",
            "    p0 -> p1;\n",
            "    p0 -> p2;\n",
            "    p1[label=\"b\" ];\n",
            "    p1 -> p3;\n",
            "    p2[label=\"c\" ];\n",
            "    p2 -> p3;\n",
            "    p3[label=\"d\" ];\n",
            "  }\n",
            "}\n",
        )
    );
}

/// `Display` is the same document, so `{taskflow}` and `println!` need no
/// `dump()` call. Asserted against the diamond golden's own body so the two
/// paths cannot drift apart.
#[test]
fn display_writes_the_same_document() {
    let mut taskflow = Taskflow::with_name("displayed");
    let graph = taskflow.graph_mut();
    let a = graph.add_named_node("a", Handle::Placeholder);
    let b = graph.add_node(Handle::Placeholder);
    graph.add_edge(a, b);

    assert_eq!(
        format!("{taskflow}"),
        concat!(
            "digraph Taskflow {\n",
            "  compound=true;\n",
            "  subgraph cluster_p0 {\n",
            "    label=\"Taskflow: displayed\";\n",
            "    p0[label=\"a\" ];\n",
            "    p0 -> p1;\n",
            "    p1[label=\"p1\" ];\n",
            "  }\n",
            "}\n",
        )
    );
    assert_eq!(taskflow.dump(), taskflow.to_string());
}

/// The graph-level entry point emits the cluster body alone -- upstream's
/// per-graph `_dump`, which is a fragment and not a document.
#[test]
fn a_graph_dumps_only_the_cluster_body() {
    let mut taskflow = Taskflow::with_name("diamond");
    let graph = taskflow.graph_mut();
    let a = graph.add_named_node("a", Handle::Placeholder);
    let b = graph.add_named_node("b", Handle::Placeholder);
    graph.add_edge(a, b);

    let mut body = String::new();
    taskflow
        .graph()
        .dump_into(&mut body)
        .expect("writing to a String cannot fail");

    assert_eq!(
        body,
        concat!(
            "    p0[label=\"a\" ];\n",
            "    p0 -> p1;\n",
            "    p1[label=\"b\" ];\n",
        )
    );
    // And it is literally the document minus the wrapper.
    assert!(taskflow.dump().contains(&body));
}
